232	    @Override
233	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
234	        HttpHeaders headers = new HttpHeaders();
235	        Visit visit = visitMapper.toVisit(visitFieldsDto);
236	        Pet pet = new Pet();
237	        pet.setId(petId);
238	        visit.setPet(pet);
239	        this.clinicService.saveVisit(visit);
240	        VisitDto visitDto = visitMapper.toVisitDto(visit);
241	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
242	            .buildAndExpand(visit.getId()).toUri());
