244	    }
245	
246	
247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Override
249	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner != null) {
252	            Pet pet = owner.getPet(petId);
253	            if (pet != null) {
254	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
255	            }
256	        }
257	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	    }
259	
260	    /**
261	     * Builds the customer code for a newly created owner, formatted
262	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
263	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
264	     * sequence equal to one more than the current number of owners.
265	     *
266	     * @param lastName the owner's last name
267	     * @return the assigned customer code (e.g. {@code 'SMI-0007'})
268	     */
269	    private String nextCustomerCode(String lastName) {
270	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
271	        int sequence = this.clinicService.findAllOwners().size() + 1;
272	        return String.format("%s-%04d", last3, sequence);
273	    }
274	
275	    /**
276	     * Builds the membership number for a newly created owner, formatted
277	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
278	     * customer code and {@code YY} is the last two digits of the owner's registration
279	     * date year, zero-padded to two digits.
280	     *
281	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SMI-0007'})
282	     * @param registrationDate the owner's registration date
283	     * @return the assigned membership number (e.g. {@code 'SMI-0007-M26'})
284	     */
285	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
286	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
287	    }
288	
289	    /**
290	     * Counts how many existing owners share the given first and last name, compared
291	     * case-insensitively. This is evaluated before the new owner is persisted, so the
292	     * owner being created is not included in the count.
293	     *
294	     * @param firstName the new owner's first name
295	     * @param lastName  the new owner's last name
296	     * @return the number of existing owners with the same first and last name
297	     */
298	    private int countNamesakes(String firstName, String lastName) {
299	        int count = 0;
300	        for (Owner existing : this.clinicService.findAllOwners()) {
301	            if (firstName.equalsIgnoreCase(existing.getFirstName())
302	                && lastName.equalsIgnoreCase(existing.getLastName())) {
303	                count++;
304	            }
305	        }
306	        return count;
307	    }
308	
309	    /**
310	     * Canonical expansions applied to common street-type abbreviations during address
311	     * normalization. Keys and values are upper-cased so the lookup runs after the address
312	     * has itself been upper-cased.
313	     */
314	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
315	        "ST", "STREET",
316	        "RD", "ROAD",
317	        "AVE", "AVENUE");
318	
319	    /**
320	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
321	     * every run of internal whitespace is collapsed to a single space, the result is
322	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
323	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
324	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
325	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
326	     * returned and compared for household duplicates; an address that is blank once
327	     * normalized fails the required-field check.
328	     *
329	     * @param address the raw address value supplied by the client
330	     * @return the normalized address (empty string when {@code address} is null or blank)
331	     */
332	    private static String normalizeAddress(String address) {
333	        if (address == null) {
334	            return "";
335	        }
336	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
337	        if (collapsed.isEmpty()) {
338	            return "";
339	        }
340	        StringBuilder normalized = new StringBuilder(collapsed.length());
341	        for (String token : collapsed.split(" ")) {
342	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
343	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
344	            if (normalized.length() > 0) {
345	                normalized.append(' ');
346	            }
347	            normalized.append(expanded != null ? expanded : token);
348	        }
349	        return normalized.toString();
350	    }
351	
352	    /**
353	     * Normalizes a last name or address for household-duplicate comparison: leading and
354	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
355	     * single space and the result is lower-cased. Two owners are considered to share a
356	     * household when both their last names and addresses produce the same key.
357	     *
358	     * @param value the raw last name or address value
359	     * @return the normalized comparison key (empty string when {@code value} is null)
360	     */
361	    private static String householdKey(String value) {
362	        if (value == null) {
363	            return "";
364	        }
365	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
366	    }
367	
368	    /**
369	     * Derives the stable shared household identifier for the given normalized last name
370	     * and address keys. The identifier is deterministic — the same household (same
371	     * {@link #householdKey normalized} last name and address) always maps to the same
372	     * value — so every owner who joins a household is assigned an identical id. It is the
373	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
374	     * '<lastNameKey>|<addressKey>'}.
375	     *
376	     * @param lastNameKey the normalized last name key
377	     * @param addressKey  the normalized address key
378	     * @return the shared household identifier
379	     */
380	    private static String householdId(String lastNameKey, String addressKey) {
381	        String source = lastNameKey + "|" + addressKey;
382	        try {
383	            byte[] digest = MessageDigest.getInstance("SHA-256")
384	                .digest(source.getBytes(StandardCharsets.UTF_8));
385	            StringBuilder hex = new StringBuilder(digest.length * 2);
386	            for (byte b : digest) {
387	                hex.append(String.format("%02x", b));
388	            }
389	            return hex.substring(0, 12).toUpperCase();
390	        } catch (NoSuchAlgorithmException e) {
391	            throw new IllegalStateException("SHA-256 not available", e);
392	        }
393	    }
394	
395	    /**
396	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
397	     * and brackets are stripped. When the number already carries a leading {@code '+'}
398	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
399	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
400	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
401	     *
402	     * @param telephone the raw telephone value supplied by the client
403	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
404	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
405	     */
406	    private static String toE164(String telephone) {
407	        if (telephone == null) {
408	            return null;
409	        }
410	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
411	        String digits;
412	        if (cleaned.startsWith("+")) {
413	            digits = cleaned.substring(1);
414	        } else {
415	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
416	            digits = "61" + national;
417	        }
418	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
419	    }
420	
421	    /**
422	     * Normalizes an owner email for creation. A present email must be a syntactically
423	     * valid address; the returned value is lower-cased.
424	     *
425	     * @param email the raw email value supplied by the client (never {@code null} here)
426	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
427	     *         address (signalling a 400 Bad Request)
428	     */
429	    private static String normalizeEmail(String email) {
430	        String trimmed = email.trim();
431	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
432	            return null;
433	        }
434	        return trimmed.toLowerCase();
435	    }
436	}
